const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Antakya location (capital of Hatay Province, Turkey)
  const antakya = ee.Geometry.Point([36.16, 36.2]);
  const region = antakya.buffer(5000); // 5km buffer around city center

  // Date ranges for the two comparison dates
  const date1Start = '2023-02-01';
  const date1End = '2023-02-28';
  const date2Start = '2023-04-01';
  const date2End = '2023-04-30';

  console.log('Analyzing nighttime lights in Antakya, Turkey');
  console.log('Date 1: February 2023');
  console.log('Date 2: April 2023');

  // Load VIIRS nighttime lights monthly composites
  const viirs1 = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
    .filterDate(date1Start, date1End)
    .filterBounds(region);

  const viirs2 = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
    .filterDate(date2Start, date2End)
    .filterBounds(region);

  const count1 = viirs1.size().getInfo();
  const count2 = viirs2.size().getInfo();

  console.log(`Feb 2023 Images: ${count1}`);
  console.log(`Apr 2023 Images: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log('Missing data for one or both periods');
    console.log('<answer>C1</answer>');
    return;
  }

  // Get the first (and typically only) image from each period
  const img1 = viirs1.first();
  const img2 = viirs2.first();

  // Calculate mean nighttime light intensity for both periods
  const stats1 = img1.select('avg_rad').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2 = img2.select('avg_rad').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  // Also get pixel counts
  const count_stats1 = img1.select('avg_rad').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  const count_stats2 = img2.select('avg_rad').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  const intensity1 = stats1.get('avg_rad').getInfo();
  const intensity2 = stats2.get('avg_rad').getInfo();
  const pixels1 = count_stats1.get('avg_rad').getInfo();
  const pixels2 = count_stats2.get('avg_rad').getInfo();

  console.log(`Feb 2023: Intensity=${intensity1}, Pixels=${pixels1}`);
  console.log(`Apr 2023: Intensity=${intensity2}, Pixels=${pixels2}`);

  if (pixels1 === 0 || pixels2 === 0) {
    console.log('No valid pixels in one or both periods');
    console.log('<answer>C2</answer>');
    return;
  }

  if (intensity1 === null || intensity2 === null || 
      isNaN(intensity1) || isNaN(intensity2) ||
      intensity1 < 0 || intensity2 < 0) {
    console.log('Invalid calculation results');
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare intensities
  console.log(`Difference (Feb - Apr): ${(intensity1 - intensity2).toFixed(4)}`);

  if (intensity1 > intensity2) {
    console.log('February 2023 had higher nighttime light intensity');
    console.log('<answer>A</answer>');
  } else {
    console.log('April 2023 had equal or higher nighttime light intensity');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
